result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF("seconds", join_date, MIN(transactions_made.date_time)) / 86400
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

result = Users.WHERE(LOWER(country) == LOWER('US')).CALCULATE(
    num_transactions = COUNT(transactions_sent.WHERE(
        DATEDIFF("days", created_at, DATETIME('now')) <= 7
    )),
    total_amount = SUM(transactions_sent.WHERE(
        DATEDIFF("days", created_at, DATETIME('now')) <= 7
    ).amount)
).CALCULATE(
    number_of_transactions = SUM(num_transactions),
    total_transaction_amount = SUM(total_amount)
).SINGULAR()

user_session_duration = Users.CALCULATE(
    user_id=uid,
    total_duration=ROUND(
        SUM(
            sessions.WHERE(
                (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
            ).CALCULATE(
                duration_secs=DATEDIFF("seconds", session_start_ts, session_end_ts)
            ).duration_secs
        ), 0
    )
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

result = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("days", user.created_at, created_at) <= 365
        )
    ) == 1
).CALCULATE(
    user_name=username,
    user_email=email,
    signup_date=created_at
)
